"""Original diabetes chapter: individualized control, insulin and technology."""
from create_diabetes_phenotypes import rows,q,DX,T1,MO,PR,TZ
from qbank_authoring import ref,finalize
GL=ref('ADA Standards—2026: Glycemic Goals, Hypoglycemia and Hyperglycemic Crises','https://doi.org/10.2337/dc26-s006')
TE=ref('ADA Standards—2026: Diabetes Technology','https://doi.org/10.2337/dc26-s007')
PH=ref('ADA Standards—2026: Pharmacologic Approaches','https://diabetesjournals.org/care/article/49/Supplement_1/S183/163934/9-Pharmacologic-Approaches-to-Glycemic-Treatment')
RE=ref('International Consensus: Definition and Interpretation of Remission in Type 2 Diabetes','https://pmc.ncbi.nlm.nih.gov/articles/PMC8929179/')
for item in rows:
 if 'three months without glucose-lowering' in item['question']:item['references'].append(RE)
q('Which A1C target is appropriate for many nonpregnant adults when achievable without significant hypoglycemia or excessive treatment burden?', 'Below 7%, individualized to the person',[
 ('Below 5% is mandatory for every adult','This can create excessive hypoglycemia and burden.'),('Below 9% is the universal target for all young healthy adults','This is unnecessarily permissive for many people.'),('The same target applies regardless of frailty or severe hypoglycemia','Goals require individualization.')],
 'The target is a benefit-risk decision', '**An A1C below 7% is suitable for many adults.**',['Lower targets may suit selected people with low risk and long life expectancy.','Frailty, limited prognosis and recurrent severe hypoglycemia can justify less stringent goals.'], '**Reassess goals when circumstances change.**',['Include treatment burden and preferences.','Avoid equating a lower number with better care in every situation.'],[['Common target','A1C below 7%'],['Tighter goal','Selected low-risk circumstances'],['Relaxation','When harms or burden outweigh benefit']],[GL])
q('A frail older adult on insulin has A1C 6.2% and recurrent episodes requiring assistance. What is the best management principle?', 'Deintensify or simplify the hypoglycemia-causing regimen and individualize the goal',[
 ('Increase insulin because all A1C values should be below 6%','This intensifies a documented harm.'),('Ignore the episodes because the average is excellent','Average glycemia can conceal dangerous lows.'),('Stop all glucose monitoring permanently','Monitoring helps safely revise treatment.')],
 'A low average can hide unsafe variability', '**Recurrent severe hypoglycemia is a reason to reassess treatment regardless of A1C.**',['Kidney impairment, cognition and meal irregularity can increase risk.','Simpler regimens and lower-risk agents may reduce burden.'], '**Prioritize avoidance of lows and symptomatic hyperglycemia.**',['Include caregivers and practical capacity.','Do not describe deintensification as failure.'],[['Signal','Low A1C plus severe episodes'],['Priority','Reduce treatment harm'],['Plan','Simplify and individualize']],[GL],'clinical_scenario')
q('A clinically stable patient is at goal with no recent treatment change. How often is A1C commonly assessed?', 'At least twice yearly, with more frequent assessment when control or therapy changes',[
 ('Only once every five years','This is too infrequent for routine diabetes follow-up.'),('Every day as the main short-term dose guide','A1C does not change meaningfully on a daily treatment timescale.'),('Never if CGM is used','A1C and CGM provide complementary information where A1C is reliable.')],
 'Monitoring frequency reflects stability', '**Quarterly assessment is commonly used when not at goal or after treatment changes.**',['A1C reflects prior weeks to months and weights recent exposure more heavily.','Immediate decisions use measured glucose or CGM patterns.'], '**Choose tests that answer the current question.**',['Check for A1C interference when discordant.','Do not wait for a quarterly test to respond to recurrent hypoglycemia.'],[['Stable at goal','At least twice yearly'],['Changing/not at goal','Often about every three months'],['Immediate dosing','Glucose and trends']],[GL])
q('For many nonpregnant adults using CGM, what is the usual time-in-range goal for glucose 70–180 mg/dL?', 'More than 70% of readings',[
 ('More than 20% for every otherwise healthy adult','This is substantially below the usual goal.'),('Exactly 100% is required before treatment is considered successful','This is generally unrealistic and can promote unsafe treatment.'),('Time in range is irrelevant if A1C is available','CGM reveals variability and hypoglycemia not fully represented by A1C.')],
 'The distribution matters as well as the mean', '**A time in range above 70% is suitable for many adults.**',['Time below 70 should generally be below 4% and below 54 below 1%.','Targets differ for pregnancy and high-risk older adults.'], '**Reduce hypoglycemia before pursuing extra range at its expense.**',['Use a representative sensor period.','Review daily patterns rather than only a summary percentage.'],[['Range','70–180 mg/dL'],['Common TIR goal','Above 70%'],['Safety','Minimize time below range']],[GL,TE])
q('A1C and CGM-derived glucose management indicator differ substantially. What is the most appropriate interpretation?', 'Investigate sampling, glycemic timing and factors altering A1C rather than treating the two estimates as interchangeable',[
 ('GMI is a directly measured hemoglobin glycation assay','It is calculated from sensor mean glucose.'),('One discordance proves deliberate nonadherence','Biology, device issues and different time windows can explain it.'),('The lower value is always the correct treatment target','Neither should be selected without context.')],
 'Two metrics can sample different biology and time periods', '**GMI estimates an A1C-like value from mean CGM glucose.**',['Red-cell turnover affects A1C but not GMI in the same way.','A recent glucose change may not yet be reflected fully in A1C.'], '**Check data completeness and plausible interference.**',['Compare with capillary or laboratory glucose when needed.','Use a clinically safe pattern-based plan.'],[['A1C','Hemoglobin exposure and lifespan'],['GMI','Sensor-derived estimate'],['Discordance','Requires interpretation']],[GL,TE])
q('During rapidly falling glucose, sensor and capillary values differ and symptoms do not match the CGM display. What should the user do?', 'Confirm with a capillary measurement using the device’s safety instructions and treat clinically significant hypoglycemia promptly',[
 ('Always trust the sensor regardless of symptoms','Interstitial lag or sensor problems can create a mismatch.'),('Ignore symptoms until the next A1C','A1C cannot resolve an acute event.'),('Calibrate every sensor in the same way regardless of manufacturer','Calibration and interference instructions vary by device.')],
 'CGM measures interstitial rather than direct blood glucose', '**Lag is more evident during rapid change.**',['Pressure effects and device-specific interferents can also affect readings.','Users still need access to a capillary meter.'], '**Teach the circumstances that require confirmation.**',['Do not delay emergency care for severe symptoms.','Review sensor placement and device-specific guidance after the event.'],[['CGM compartment','Interstitial fluid'],['Mismatch','Rapid change or device issue'],['Backup','Capillary testing supplies']],[TE,T1],'clinical_scenario')
q('Why must a person with type 1 diabetes generally continue basal insulin even when not eating?', 'Basal insulin suppresses hepatic glucose production and ketogenesis between meals',[
 ('Basal insulin only covers the carbohydrate in the next meal','That is the main role of prandial insulin.'),('Fasting eliminates the risk of ketone production','Insulin deficiency can produce ketosis during fasting.'),('Correction-only insulin is a complete basal replacement','Reactive doses do not reliably provide continuous coverage.')],
 'Food-related and background insulin needs differ', '**Absolute insulin deficiency creates a continuing requirement for basal coverage.**',['The exact dose may need adjustment during fasting or illness.','Prandial doses are matched to intake and current glucose.'], '**Use a sick-day or fasting plan rather than stopping all insulin.**',['Monitor glucose and ketones when indicated.','Seek urgent advice for vomiting, ketones or inability to maintain fluids.'],[['Basal','Fasting glucose and ketone suppression'],['Bolus','Meals and correction'],['Fasting','Adjust safely; do not omit all insulin']],[PH,T1])
q('A taught insulin-to-carbohydrate ratio is 1 unit per 12 g. For a meal containing 60 g carbohydrate, with no correction or active-insulin adjustment needed, what meal dose follows the stated ratio?', '5 units',[
 ('2 units','This would cover only 24 g using the stated ratio.'),('12 units','This is not 60 divided by 12.'),('20 units','This greatly exceeds the stated ratio calculation.')],
 'Apply the prescribed ratio, not a universal meal dose', '**Meal carbohydrate divided by grams covered per unit gives the carbohydrate dose.**',['Here 60/12 equals 5 units.','Real-life dosing also considers current glucose, trend, active insulin, activity and meal composition.'], '**Use the individual taught plan.**',['A ratio is not interchangeable between patients or all times of day.','Avoid presenting a worked arithmetic example as a new prescription.'],[['Carbohydrate','60 g'],['Ratio','12 g/unit'],['Calculated component','5 units']],[PH,T1])
q('A patient’s taught correction factor is 1 unit per 50 mg/dL above a target of 120. Glucose is 270 mg/dL with no active insulin or other adjustment. What correction component follows that plan?', '3 units',[
 ('1 unit','The difference is 150, not 50 mg/dL.'),('5 units','This exceeds the specified factor calculation.'),('6 units','This would double the calculated component.')],
 'A correction factor estimates a patient-specific glucose response', '**Correction component = (current glucose − target) / sensitivity factor.**',['Here (270 − 120)/50 equals 3.','Active insulin and trends can materially change a safe actual dose.'], '**Avoid insulin stacking.**',['Check the timing of recent boluses.','Follow the individualized plan rather than repeating corrections at short intervals.'],[['Difference','150 mg/dL'],['Factor','50 mg/dL/unit'],['Calculated component','3 units']],[PH,T1])
q('A patient has fasting hyperglycemia. CGM shows stable overnight values followed by an early-morning rise without preceding hypoglycemia. What is the best interpretation?', 'A dawn-related increase in glucose production or inadequate early-morning insulin coverage',[
 ('Rebound after nocturnal hypoglycemia is established','The sensor record shows no preceding low.'),('The meal carbohydrate ratio must be the only problem','The rise occurs before breakfast.'),('Insulin should always be reduced regardless of the pattern','Dose direction depends on the documented mechanism.')],
 'Use overnight data before changing basal therapy', '**Early-morning hormonal and hepatic effects can increase insulin requirements.**',['Late meals and waning insulin can contribute.','Do not assume a Somogyi mechanism without evidence of nocturnal lows.'], '**Adjust the relevant timing or basal profile safely.**',['Review bedtime intake and dose history.','Continue monitoring after any change.'],[['No preceding low','Dawn/coverage explanation favored'],['Documented nocturnal low','Different safety response'],['Data source','Overnight glucose pattern']],[PH,TE],'clinical_scenario')
q('Repeated injections into a painless thickened abdominal area are associated with erratic absorption and unexplained hypoglycemia. What is the likely problem?', 'Injection-site lipohypertrophy',[
 ('Uniformly predictable absorption from scarred tissue','Absorption can be variable.'),('A new diagnosis of insulin allergy is proven','Thickened repeatedly used sites suggest lipohypertrophy.'),('Only dietary nonadherence can produce variability','Injection technique is an important alternative.')],
 'Examine injection sites before escalating doses', '**Repeated use of the same area can produce abnormal subcutaneous tissue.**',['Insulin absorption becomes less predictable.','Moving to unaffected tissue can increase effective absorption.'], '**Rotate sites and reassess dosing with close glucose monitoring.**',['Teach a systematic rotation plan.','Do not continue the same high dose blindly after changing from abnormal tissue.'],[['Clue','Repeated injections into thickened area'],['Effect','Variable absorption'],['Correction','Site rotation and dose review']],[PH,T1],'clinical_scenario')
q('An insulin pump infusion set becomes disconnected in a person with type 1 diabetes. Why can ketosis develop relatively quickly?', 'There may be no long-acting subcutaneous insulin depot to provide background coverage',[
 ('Pump users cannot develop DKA','Delivery interruption is a recognized risk.'),('All pumps contain enough long-acting insulin for several days','Most use rapid-acting insulin for continuous delivery.'),('A normal glucose at the moment of disconnection guarantees ongoing safety','Glucose and ketones can rise subsequently.')],
 'Continuous delivery creates dependence on circuit integrity', '**Rapid-acting pump insulin has a limited residual effect after interruption.**',['Illness increases vulnerability.','High glucose should prompt an infusion-set and ketone check according to the plan.'], '**Have an injection backup and written failure instructions.**',['Do not keep correcting through a demonstrably failed site.','Seek care for ketones, vomiting or persistent hyperglycemia.'],[['Pump insulin','Usually rapid acting'],['Failure risk','Loss of basal delivery'],['Backup','Injection and ketone plan']],[TE,T1],'clinical_scenario')
q('Which statement best describes automated insulin delivery for a suitable person with type 1 diabetes?', 'It uses CGM-informed algorithms to adjust insulin delivery and is generally preferred when it can be used safely',[
 ('It eliminates the need for education, backup supplies and follow-up','Users still need these safeguards.'),('It guarantees that meal input and exercise planning are never needed on any system','Requirements differ by device and many systems remain hybrid.'),('It directly measures blood insulin concentrations','The control input is chiefly sensor glucose and algorithmic information.')],
 'Automation improves delivery but does not remove all responsibilities', '**AID integrates a sensor, pump and control algorithm.**',['It can improve time in range and reduce burden.','System capabilities and meal-announcement requirements vary.'], '**Choose a system that fits the person’s capacity and preferences.**',['Train for sensor and infusion failures.','Keep capillary and ketone testing plus backup insulin available.'],[['Components','CGM, pump and algorithm'],['Benefit','Responsive insulin adjustment'],['Safety','Training and failure backup']],[TE,T1])
q('A person with type 1 diabetes has fever and poor appetite but is not vomiting. What is the best general sick-day principle?', 'Continue necessary basal insulin, monitor glucose and ketones more often and maintain an individualized fluid and correction plan',[
 ('Stop all insulin because no full meals are eaten','This can precipitate DKA.'),('Check only A1C after recovery','Acute glucose and ketone monitoring is needed.'),('Give unlimited repeated correction boluses without tracking active insulin','This can cause insulin stacking and hypoglycemia.')],
 'Illness can increase insulin needs despite reduced intake', '**Counterregulatory hormones can drive glucose production and ketogenesis.**',['Hydration and access to carbohydrate may be needed.','The actual insulin plan depends on glucose, ketones and usual regimen.'], '**Use clear escalation criteria.**',['Vomiting, rising ketones, dehydration or inability to follow the plan needs urgent assessment.','Include backup delivery instructions for pump users.'],[['Basal insulin','Usually continues with individualized adjustment'],['Monitoring','Glucose and ketones'],['Escalation','Ketones, vomiting or dehydration']],[T1,PH],'clinical_scenario')
q('A person on insulin develops nocturnal hypoglycemia after prolonged afternoon aerobic exercise. Which mechanism is most relevant?', 'Persistently increased insulin sensitivity and replenishment of muscle glycogen after activity',[
 ('Exercise can influence glucose only while it is occurring','Delayed hypoglycemia is recognized.'),('All exercise invariably causes sustained hyperglycemia','Response depends on intensity, insulin and duration.'),('The event proves the CGM must be inaccurate','Confirm as appropriate, but the physiological risk is real.')],
 'Exercise planning extends beyond the activity itself', '**Muscle glucose uptake and sensitivity can remain increased after exercise.**',['Hypoglycemia risk depends on insulin on board, duration and food intake.','Very intense activity can transiently raise glucose, producing a different pattern.'], '**Plan carbohydrates, insulin adjustments and overnight surveillance individually.**',['Use CGM alerts or targeted capillary checks as appropriate.','Avoid a universal reduction rule detached from the person’s response.'],[['Aerobic exercise','Often lowers glucose'],['Afterward','Delayed sensitivity and glycogen replacement'],['Plan','Food, insulin and monitoring']],[T1,TE],'clinical_scenario')
q('Why is diabetes self-management education recommended again at transitions such as new complications or major regimen changes?', 'Skills and support needs change as the disease, treatment and personal circumstances change',[
 ('A one-time diagnosis lecture always provides lifelong sufficient skills','Needs evolve and skills can require reinforcement.'),('Education replaces access to necessary medicines and monitoring','Practical resources and medical care remain essential.'),('It should be limited to people with poor motivation','All people can benefit from timely support.')],
 'Education is an ongoing clinical intervention', '**Critical times include diagnosis, unmet goals, complicating factors and care transitions.**',['Numeracy, language, cost and health literacy affect feasibility.','Emotional distress and fear of hypoglycemia deserve assessment.'], '**Use practical shared goals and demonstrations.**',['Confirm understanding without blame.','Connect education with nutrition, technology and psychosocial support as needed.'],[['Timing','Diagnosis and changing needs'],['Method','Individualized practical skills'],['Goal','Safe sustainable self-management']],[T1,PH])

if __name__=='__main__':finalize('Endocrine',1,'Diabetes Mellitus','endo-diabetes',rows,48)
